class Solution:
    def wordsTyping(self, sentence: List[str], rows: int, cols: int) -> int:
        s = ' '.join(sentence)
        L = len(s)
        if max(len(w) for w in sentence) > cols:
            return 0
        cnt = 0
        for _ in range(rows):
            cnt += cols + 1
            if s[cnt % L] == ' ':
                cnt += 1
            else:
                while cnt > 0 and s[(cnt - 1) % L] != ' ':
                    cnt -= 1
        return cnt // L

