class Solution {
public:
    int wordsTyping(vector<string>& sentence, int rows, int cols) {
        string s;
        for (auto& w : sentence) { s += w; s += ' '; }
        long long L = s.size();
        for (auto& w : sentence) if ((int)w.size() > cols) return 0;
        long long cnt = 0;
        for (int r = 0; r < rows; r++) {
            cnt += cols + 1;
            if (s[cnt % L] == ' ') cnt++;
            else {
                while (cnt > 0 && s[(cnt - 1) % L] != ' ') cnt--;
            }
        }
        return cnt / L;
    }
};

