class Solution {
    public int wordsTyping(String[] sentence, int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (String w : sentence) sb.append(w).append(' ');
        String s = sb.toString();
        int L = s.length();
        for (String w : sentence) if (w.length() > cols) return 0;
        long cnt = 0;
        for (int r = 0; r < rows; r++) {
            cnt += cols + 1;
            if (s.charAt((int)(cnt % L)) == ' ') cnt++;
            else {
                while (cnt > 0 && s.charAt((int)((cnt - 1) % L)) != ' ') cnt--;
            }
        }
        return (int)(cnt / L);
    }
}

