var wordsTyping = function(sentence, rows, cols) {
    const s = sentence.join(' ') + ' ';
    const L = s.length;
    if (Math.max(...sentence.map(w => w.length)) > cols) return 0;
    let cnt = 0;
    for (let r = 0; r < rows; r++) {
        cnt += cols + 1;
        if (s[cnt % L] === ' ') cnt++;
        else {
            while (cnt > 0 && s[(cnt - 1) % L] !== ' ') cnt--;
        }
    }
    return Math.floor(cnt / L);
};

