class Solution:
    def wordsTyping(self, sentence: List[str], rows: int, cols: int) -> int:
        n = len(sentence)
        if max(len(w) for w in sentence) > cols:
            return 0
        count = [0] * n
        nxt = [0] * n
        for i in range(n):
            cur, j, c = 0, i, 0
            while cur + len(sentence[j]) <= cols:
                cur += len(sentence[j]) + 1
                j += 1
                if j == n:
                    j = 0
                    c += 1
            count[i] = c
            nxt[i] = j
        res, idx = 0, 0
        for _ in range(rows):
            res += count[idx]
            idx = nxt[idx]
        return res

